create policy "surveys_read"
on "public"."surveyAnswers"
as permissive
for select
to authenticated
using ((isuseradmin(auth.uid()) OR (isuserinorg(organisation, auth.uid()) AND ((((getuserpermissionsobject(auth.uid(), 'surveys'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean)));


