create policy "notification_read"
on "public"."notifications"
as permissive
for select
to authenticated
using ((isuseradmin(auth.uid()) OR (isuserinorg(organisation, auth.uid()) AND notificationrecordexistsforuser(id, auth.uid()) AND (((type = 'news'::"NotificationType") AND ((((getuserpermissionsobject(auth.uid(), 'news'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean) OR ((type = 'survey'::"NotificationType") AND ((((getuserpermissionsobject(auth.uid(), 'surveys'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean) OR ((type = 'report'::"NotificationType") AND ((((getuserpermissionsobject(auth.uid(), 'organisationReports'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean) OR (type = 'notification'::"NotificationType")))));



